import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mx_textureSample, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. GEOMETRY & MATERIAL
  // ============================================================================
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);
  const material = new MeshBasicNodeMaterial();

  // Load texture and assign
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((texture) => {
      material.colorNode = mx_textureSample(texture, uv());
      material.needsUpdate = true;
    });

  const mesh = new THREE.Mesh(geometry, material);

  // ============================================================================
  // 2. SCENE GROUP & POSITIONING
  // ============================================================================
  const group = new THREE.Group();
  group.add(mesh);

  // Apply scene position from config (adapter will also apply, but we set it here for safety)
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x ?? 0,
      config.scenePosition.y ?? 0,
      config.scenePosition.z ?? 0
    );
  }

  // ============================================================================
  // 3. INTERACTION STATE & TIMELINES
  // ============================================================================
  const timelines = [];
  let isPressed = false;

  // ============================================================================
  // 4. HOVER INTERACTION (rise-in: lift 0.15 units, power3.out, 0.7s)
  // ============================================================================
  const onHoverEnter = () => {
    // Kill any in-flight hover timeline
    timelines.forEach((tl) => {
      if (tl._isHoverTimeline) tl.kill();
    });

    const hoverTl = gsap.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto',
    });
    hoverTl._isHoverTimeline = true;
    timelines.push(hoverTl);
  };

  const onHoverExit = () => {
    // Settle back with weighted-settle (overshoot 1.04 -> 1.0, power4.out, 0.9s)
    timelines.forEach((tl) => {
      if (tl._isHoverTimeline) tl.kill();
    });

    const settleTl = gsap.to(group.position, {
      y: group.position.y - 0.15,
      duration: 0.9,
      ease: 'power4.out',
      overwrite: 'auto',
    });
    timelines.push(settleTl);
  };

  // ============================================================================
  // 5. CLICK INTERACTION (press-down scale 0.97, 120ms, back.out + emit event)
  // ============================================================================
  const onMouseDown = () => {
    isPressed = true;
    timelines.forEach((tl) => {
      if (tl._isPressTimeline) tl.kill();
    });

    const pressTl = gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
      overwrite: 'auto',
    });
    pressTl._isPressTimeline = true;
    timelines.push(pressTl);
  };

  const onMouseUp = () => {
    if (!isPressed) return;
    isPressed = false;

    // Scale back to 1.0
    timelines.forEach((tl) => {
      if (tl._isPressTimeline) tl.kill();
    });

    const releaseTl = gsap.to(group.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.12,
      ease: 'back.out',
      overwrite: 'auto',
    });
    timelines.push(releaseTl);

    // Emit navigation event
    ctx.emit('navigate', { to: 'hub-journal' });
  };

  // ============================================================================
  // 6. ATTACH EVENT HANDLERS
  // ============================================================================
  group.userData.handlers = {
    onHoverEnter,
    onHoverExit,
    onMouseDown,
    onMouseUp,
  };

  // ============================================================================
  // 7. CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    geometry.dispose();
    material.dispose();
  };

  return group;
}
